// A Qualifier controls how named package-level objects are printed in
// calls to [TypeString], [ObjectString], and [SelectionString].
//
// These three formatting routines call the Qualifier for each
// package-level object O, and if the Qualifier returns a non-empty
// string p, the object is printed in the form p.O.
// If it returns an empty string, only the object name O is printed.
//
// Using a nil Qualifier is equivalent to using (*[Package]).Path: the
// object is qualified by the import path, e.g., "encoding/json.Marshal".
export type Qualifier = (pkg: Package) => string;

// RelativeTo returns a [Qualifier] that fully qualifies members of
// all packages other than pkg.
export function RelativeTo(pkg: Package | null): Qualifier | null {
  if (pkg === null) {
    return null;
  }
  return (other: Package): string => {
    if (pkg === other) {
      return ""; // same package; unqualified
    }
    return other.Path();
  };
}

// TypeString returns the string representation of typ.
// The [Qualifier] controls the printing of
// package-level objects, and may be nil.
export function TypeString(typ: Type | null, qf: Qualifier | null = null): string {
  const buf: string[] = [];
  WriteType(buf, typ, qf);
  return buf.join("");
}

// WriteType writes the string representation of typ to buf.
// The [Qualifier] controls the printing of
// package-level objects, and may be nil.
export function WriteType(buf: string[], typ: Type | null, qf: Qualifier | null = null): void {
  newTypeWriter(buf, qf).typ(typ);
}

// WriteSignature writes the representation of the signature sig to buf,
// without a leading "func" keyword. The [Qualifier] controls the printing
// of package-level objects, and may be nil.
export function WriteSignature(buf: string[], sig: Signature, qf: Qualifier | null = null): void {
  newTypeWriter(buf, qf).signature(sig);
}

