export function newTypeWriter(buf: string[], qf: Qualifier | null): typeWriter {
  return new typeWriter(buf, new Map<Type, boolean>(), qf, null, null, true, false, false);
}

export function newTypeHasher(buf: string[], ctxt: Context): typeWriter {
  assert(ctxt !== null);
  return new typeWriter(buf, new Map<Type, boolean>(), null, ctxt, null, false, false, false);
}

// subscript returns the decimal (utf8) representation of x using subscript digits.
export function subscript(x: bigint): string {
  const digits = "₀₁₂₃₄₅₆₇₈₉";
  let s = "";
  for (;;) {
    s = Array.from(digits)[Number(x % 10n)]! + s;
    x = x / 10n;
    if (x === 0n) {
      break;
    }
  }
  return s;
}

function quoteString(s: string): string {
  return JSON.stringify(s);
}

function goTypeName(typ: Type): string {
  return typ.constructor.name.replaceAll("types.", "");
}
